PARTNERS_HTML = '<style>\n.partner-cat{margin-top:34px}\n.partner-cat h2{margin-bottom:6px}\n.partner-cat .cat-desc{color:var(--ink-2);margin-bottom:16px}\n.partner-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:14px}\n.partner{aspect-ratio:1.55;border:1px solid var(--line);border-radius:var(--radius);background:#fff;display:grid;place-items:center;padding:14px;text-align:center;color:var(--muted);font-size:.82rem;font-style:italic;box-shadow:0 1px 2px rgba(11,37,69,.04)}\n.partner img{max-height:48px;width:auto}\n</style><div class=\'verify\'><strong>Before publishing:</strong> replace each placeholder tile with the lender\'s logo and a link to their site, only for lenders with a signed agreement and written logo permission. Remove any category with no signed lender. Do not list lenders by reputation or because competitors list them.</div><div class=\'partner-cat\'><h2>Personal loans for home improvement</h2><p class=\'cat-desc\'>Unsecured fixed-rate loans used for roofs, HVAC, remodels and other projects. The most common product homeowners are matched with.</p><div class=\'partner-grid\'><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div></div></div><div class=\'partner-cat\'><h2>Contractor financing programs</h2><p class=\'cat-desc\'>Lenders that fund jobs through partner contractors and pay the contractor at completion, including second-look lenders for lower credit scores.</p><div class=\'partner-grid\'><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div></div></div><div class=\'partner-cat\'><h2>Home equity loans and HELOCs</h2><p class=\'cat-desc\'>Secured lending for larger planned projects.</p><div class=\'partner-grid\'><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div></div></div><div class=\'partner-cat\'><h2>Equipment and commercial vehicle financing</h2><p class=\'cat-desc\'>Excavators, lifts, dump trucks, work trucks and vans for contractors.</p><div class=\'partner-grid\'><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div></div></div><div class=\'partner-cat\'><h2>Working capital and lines of credit</h2><p class=\'cat-desc\'>Short-term capital and revolving credit for construction cash flow.</p><div class=\'partner-grid\'><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div></div></div><div class=\'partner-cat\'><h2>Construction invoice factoring</h2><p class=\'cat-desc\'>Specialist factors who understand pay-when-paid clauses and retainage.</p><div class=\'partner-grid\'><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div></div></div><div class=\'partner-cat\'><h2>SBA-backed lending</h2><p class=\'cat-desc\'>Longer-term, lower-rate loans for established contracting businesses.</p><div class=\'partner-grid\'><div class=\'partner\'>[Lender logo]</div><div class=\'partner\'>[Lender logo]</div></div></div><h2 style="margin-top:40px">What we require of every lender in the network</h2><ul><li>Clear APR and fee disclosure before the borrower commits.</li><li>A stated credit-inquiry policy (soft vs hard, and when) that we can show borrowers.</li><li>No "guaranteed approval" or "no credit check" marketing.</li><li>Licensing in the states they serve.</li></ul>\n<p class="cap">Lenders may compensate AL Elite for introductions. This does not affect the rate or terms a lender offers you. See <a href="/how-we-make-money/">how we make money</a>.</p>'

